-- Lavadero de datos · Excel trabajado
-- Script para PostgreSQL: esquema, tablas, claves y datos.
-- Uso: psql -d <base_de_datos> -f lavadero_excel_postgres.sql

SET client_encoding = 'UTF8';

BEGIN;

DROP SCHEMA IF EXISTS lavadero_excel CASCADE;
CREATE SCHEMA lavadero_excel;
SET search_path TO lavadero_excel;

CREATE TABLE regiones (
    id_region TEXT PRIMARY KEY,
    nombre TEXT
);
COMMENT ON TABLE regiones IS 'Regiones de Chile.';
COMMENT ON COLUMN regiones.id_region IS 'Identificador de región';
COMMENT ON COLUMN regiones.nombre IS 'Nombre oficial de la región';

CREATE TABLE ciudades (
    id_ciudad TEXT PRIMARY KEY,
    nombre TEXT,
    id_region TEXT REFERENCES regiones (id_region)
);
COMMENT ON TABLE ciudades IS 'Ciudades agrupadas por región.';
COMMENT ON COLUMN ciudades.id_ciudad IS 'Identificador de ciudad';
COMMENT ON COLUMN ciudades.nombre IS 'Nombre de la ciudad';
COMMENT ON COLUMN ciudades.id_region IS 'Región a la que pertenece';

CREATE TABLE comunas (
    id_comuna TEXT PRIMARY KEY,
    nombre TEXT,
    id_ciudad TEXT REFERENCES ciudades (id_ciudad)
);
COMMENT ON TABLE comunas IS 'Comunas agrupadas por ciudad.';
COMMENT ON COLUMN comunas.id_comuna IS 'Identificador de comuna';
COMMENT ON COLUMN comunas.nombre IS 'Nombre de la comuna';
COMMENT ON COLUMN comunas.id_ciudad IS 'Ciudad a la que pertenece';

CREATE TABLE estados_cuenta (
    id_estado TEXT PRIMARY KEY,
    nombre TEXT
);
COMMENT ON TABLE estados_cuenta IS 'Catálogo de estados de cuenta.';
COMMENT ON COLUMN estados_cuenta.id_estado IS 'Identificador de estado';
COMMENT ON COLUMN estados_cuenta.nombre IS 'Activo / En Revisión / Inactivo';

CREATE TABLE productos_financieros (
    id_producto_financiero TEXT PRIMARY KEY,
    nombre TEXT
);
COMMENT ON TABLE productos_financieros IS 'Productos financieros contratados.';
COMMENT ON COLUMN productos_financieros.id_producto_financiero IS 'Identificador del producto';
COMMENT ON COLUMN productos_financieros.nombre IS 'Nombre del producto';

CREATE TABLE cartera_clientes (
    id_cliente TEXT PRIMARY KEY,
    rut TEXT,
    rut_dv_valido BOOLEAN,
    nombre TEXT,
    email TEXT,
    email_valido BOOLEAN,
    id_comuna TEXT REFERENCES comunas (id_comuna),
    fecha_registro DATE
);
COMMENT ON TABLE cartera_clientes IS 'Clientes de la cartera financiera.';
COMMENT ON COLUMN cartera_clientes.id_cliente IS 'Identificador del cliente (CLI-0000)';
COMMENT ON COLUMN cartera_clientes.rut IS 'RUT normalizado 12.345.678-9';
COMMENT ON COLUMN cartera_clientes.rut_dv_valido IS 'Dígito verificador correcto según módulo 11';
COMMENT ON COLUMN cartera_clientes.nombre IS 'Nombre completo en formato nombre propio';
COMMENT ON COLUMN cartera_clientes.email IS 'Email en minúsculas y sin tildes';
COMMENT ON COLUMN cartera_clientes.email_valido IS 'Cumple formato de email';
COMMENT ON COLUMN cartera_clientes.id_comuna IS 'Comuna de residencia';
COMMENT ON COLUMN cartera_clientes.fecha_registro IS 'Fecha de registro (AAAA-MM-DD)';

CREATE TABLE cuentas (
    id_cuenta TEXT PRIMARY KEY,
    id_cliente TEXT REFERENCES cartera_clientes (id_cliente),
    id_producto_financiero TEXT REFERENCES productos_financieros (id_producto_financiero),
    id_estado TEXT REFERENCES estados_cuenta (id_estado),
    monto_facturado_clp BIGINT,
    dias_morosidad BIGINT,
    nivel_riesgo TEXT
);
COMMENT ON TABLE cuentas IS 'Situación financiera de cada cliente.';
COMMENT ON COLUMN cuentas.id_cuenta IS 'Identificador de cuenta';
COMMENT ON COLUMN cuentas.id_cliente IS 'Titular de la cuenta';
COMMENT ON COLUMN cuentas.id_producto_financiero IS 'Producto contratado';
COMMENT ON COLUMN cuentas.id_estado IS 'Estado de la cuenta';
COMMENT ON COLUMN cuentas.monto_facturado_clp IS 'Monto facturado en pesos chilenos';
COMMENT ON COLUMN cuentas.dias_morosidad IS 'Días de morosidad';
COMMENT ON COLUMN cuentas.nivel_riesgo IS 'Derivado: Alto (>60 días y Activo), Medio (>30 días o En Revisión), Bajo';

CREATE TABLE segmentos (
    id_segmento TEXT PRIMARY KEY,
    nombre TEXT
);
COMMENT ON TABLE segmentos IS 'Segmentos de cliente.';
COMMENT ON COLUMN segmentos.id_segmento IS 'Identificador de segmento';
COMMENT ON COLUMN segmentos.nombre IS 'VIP / Corporativo / Pyme / Persona';

CREATE TABLE clientes (
    id_cliente TEXT PRIMARY KEY,
    rut TEXT,
    rut_dv_valido BOOLEAN,
    nombre TEXT,
    id_segmento TEXT REFERENCES segmentos (id_segmento),
    id_comuna TEXT REFERENCES comunas (id_comuna)
);
COMMENT ON TABLE clientes IS 'Clientes del módulo de ventas.';
COMMENT ON COLUMN clientes.id_cliente IS 'Identificador del cliente (CLI-000)';
COMMENT ON COLUMN clientes.rut IS 'RUT normalizado 12.345.678-9';
COMMENT ON COLUMN clientes.rut_dv_valido IS 'Dígito verificador correcto según módulo 11';
COMMENT ON COLUMN clientes.nombre IS 'Nombre completo';
COMMENT ON COLUMN clientes.id_segmento IS 'Segmento comercial';
COMMENT ON COLUMN clientes.id_comuna IS 'Comuna del cliente';

CREATE TABLE categorias (
    id_categoria TEXT PRIMARY KEY,
    nombre TEXT
);
COMMENT ON TABLE categorias IS 'Categorías de producto.';
COMMENT ON COLUMN categorias.id_categoria IS 'Identificador de categoría';
COMMENT ON COLUMN categorias.nombre IS 'Nombre de la categoría';

CREATE TABLE productos (
    id_producto TEXT PRIMARY KEY,
    nombre TEXT,
    id_categoria TEXT REFERENCES categorias (id_categoria),
    precio_unitario_clp BIGINT
);
COMMENT ON TABLE productos IS 'Catálogo de productos y servicios.';
COMMENT ON COLUMN productos.id_producto IS 'Identificador del producto';
COMMENT ON COLUMN productos.nombre IS 'Nombre del producto';
COMMENT ON COLUMN productos.id_categoria IS 'Categoría';
COMMENT ON COLUMN productos.precio_unitario_clp IS 'Precio de lista en CLP';

CREATE TABLE zonas_comerciales (
    id_zona TEXT PRIMARY KEY,
    nombre TEXT
);
COMMENT ON TABLE zonas_comerciales IS 'Zonas comerciales de las sucursales.';
COMMENT ON COLUMN zonas_comerciales.id_zona IS 'Identificador de zona';
COMMENT ON COLUMN zonas_comerciales.nombre IS 'Nombre de la zona';

CREATE TABLE sucursales (
    id_sucursal TEXT PRIMARY KEY,
    nombre TEXT,
    id_comuna TEXT REFERENCES comunas (id_comuna),
    id_zona TEXT REFERENCES zonas_comerciales (id_zona)
);
COMMENT ON TABLE sucursales IS 'Sucursales de venta.';
COMMENT ON COLUMN sucursales.id_sucursal IS 'Identificador de sucursal';
COMMENT ON COLUMN sucursales.nombre IS 'Nombre de la sucursal';
COMMENT ON COLUMN sucursales.id_comuna IS 'Comuna de la sucursal';
COMMENT ON COLUMN sucursales.id_zona IS 'Zona comercial';

CREATE TABLE ventas (
    id_transaccion TEXT PRIMARY KEY,
    fecha_venta DATE,
    id_cliente TEXT REFERENCES clientes (id_cliente),
    id_producto TEXT REFERENCES productos (id_producto),
    id_sucursal TEXT REFERENCES sucursales (id_sucursal),
    cantidad BIGINT,
    precio_unitario_clp BIGINT,
    monto_total_clp BIGINT
);
COMMENT ON TABLE ventas IS 'Transacciones de venta válidas (tabla de hechos).';
COMMENT ON COLUMN ventas.id_transaccion IS 'Identificador de la transacción';
COMMENT ON COLUMN ventas.fecha_venta IS 'Fecha de la venta (AAAA-MM-DD)';
COMMENT ON COLUMN ventas.id_cliente IS 'Cliente comprador';
COMMENT ON COLUMN ventas.id_producto IS 'Producto vendido';
COMMENT ON COLUMN ventas.id_sucursal IS 'Sucursal de la venta';
COMMENT ON COLUMN ventas.cantidad IS 'Unidades vendidas';
COMMENT ON COLUMN ventas.precio_unitario_clp IS 'Precio unitario al momento de la venta';
COMMENT ON COLUMN ventas.monto_total_clp IS 'cantidad x precio_unitario_clp';

CREATE TABLE ventas_rechazadas (
    id_transaccion TEXT PRIMARY KEY,
    fecha_venta DATE,
    id_cliente TEXT,
    id_producto TEXT,
    id_sucursal TEXT,
    cantidad BIGINT,
    motivo TEXT
);
COMMENT ON TABLE ventas_rechazadas IS 'Ventas con claves foráneas inexistentes (cuarentena).';
COMMENT ON COLUMN ventas_rechazadas.id_transaccion IS 'Identificador de la transacción';
COMMENT ON COLUMN ventas_rechazadas.fecha_venta IS 'Fecha de la venta';
COMMENT ON COLUMN ventas_rechazadas.id_cliente IS 'Cliente informado';
COMMENT ON COLUMN ventas_rechazadas.id_producto IS 'Producto informado';
COMMENT ON COLUMN ventas_rechazadas.id_sucursal IS 'Sucursal informada';
COMMENT ON COLUMN ventas_rechazadas.cantidad IS 'Unidades';
COMMENT ON COLUMN ventas_rechazadas.motivo IS 'Motivo del rechazo';

CREATE TABLE origen_cartera (
    ID_Cliente TEXT,
    RUT_Cliente TEXT,
    Nombre_Completo TEXT,
    Email_Contacto TEXT,
    Comuna TEXT,
    Ciudad TEXT,
    Region TEXT,
    Monto_Facturado_CLP TEXT,
    Dias_Morosidad TEXT,
    Estado_Cuenta TEXT,
    Fecha_Registro TEXT
);
COMMENT ON TABLE origen_cartera IS 'Cartera financiera tal como viene en la fuente, antes del ETL.';
COMMENT ON COLUMN origen_cartera.ID_Cliente IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_cartera.RUT_Cliente IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_cartera.Nombre_Completo IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_cartera.Email_Contacto IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_cartera.Comuna IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_cartera.Ciudad IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_cartera.Region IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_cartera.Monto_Facturado_CLP IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_cartera.Dias_Morosidad IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_cartera.Estado_Cuenta IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_cartera.Fecha_Registro IS 'Valor sin limpiar';

CREATE TABLE origen_clientes (
    ID_Cliente TEXT,
    RUT_Cliente TEXT,
    Nombre_Cliente TEXT,
    Segmento TEXT,
    Comuna TEXT,
    Ciudad TEXT,
    Region TEXT
);
COMMENT ON TABLE origen_clientes IS 'Clientes comerciales tal como vienen en la fuente.';
COMMENT ON COLUMN origen_clientes.ID_Cliente IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_clientes.RUT_Cliente IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_clientes.Nombre_Cliente IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_clientes.Segmento IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_clientes.Comuna IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_clientes.Ciudad IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_clientes.Region IS 'Valor sin limpiar';

CREATE TABLE origen_productos (
    ID_Producto TEXT,
    Nombre_Producto TEXT,
    Categoria TEXT,
    Precio_Unitario_CLP TEXT
);
COMMENT ON TABLE origen_productos IS 'Productos tal como vienen en la fuente.';
COMMENT ON COLUMN origen_productos.ID_Producto IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_productos.Nombre_Producto IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_productos.Categoria IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_productos.Precio_Unitario_CLP IS 'Valor sin limpiar';

CREATE TABLE origen_sucursales (
    ID_Sucursal TEXT,
    Nombre_Sucursal TEXT,
    Comuna TEXT,
    Ciudad TEXT,
    Zona_Comercial TEXT
);
COMMENT ON TABLE origen_sucursales IS 'Sucursales tal como vienen en la fuente.';
COMMENT ON COLUMN origen_sucursales.ID_Sucursal IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_sucursales.Nombre_Sucursal IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_sucursales.Comuna IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_sucursales.Ciudad IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_sucursales.Zona_Comercial IS 'Valor sin limpiar';

CREATE TABLE origen_ventas (
    ID_Transaccion TEXT,
    Fecha_Venta TEXT,
    ID_Cliente TEXT,
    ID_Producto TEXT,
    ID_Sucursal TEXT,
    Cantidad TEXT
);
COMMENT ON TABLE origen_ventas IS 'Ventas tal como vienen en la fuente.';
COMMENT ON COLUMN origen_ventas.ID_Transaccion IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_ventas.Fecha_Venta IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_ventas.ID_Cliente IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_ventas.ID_Producto IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_ventas.ID_Sucursal IS 'Valor sin limpiar';
COMMENT ON COLUMN origen_ventas.Cantidad IS 'Valor sin limpiar';

